import threading


class StateMachine:
    def __init__(self, transitions, initial_state, *, guards=None, actions=None):
        self._transitions = dict(transitions)
        self._guards = dict(guards) if guards is not None else {}
        self._actions = dict(actions) if actions is not None else {}
        self._state = initial_state
        self._in_callback = False
        self._lock = threading.RLock()

    def current(self):
        return self._state

    def can_trigger(self, event):
        return (self._state, event) in self._transitions

    def trigger(self, event, **payload):
        with self._lock:
            if self._in_callback:
                raise RuntimeError("cannot trigger while another trigger is in progress on this machine")

            key = (self._state, event)
            if key not in self._transitions:
                raise ValueError(f"no transition for state {self._state!r} and event {event!r}")

            new_state = self._transitions[key]
            guard = self._guards.get(key)
            action = self._actions.get(key)
            payload_dict = dict(payload)

            if guard is not None:
                self._in_callback = True
                try:
                    guard_result = guard(self._state, event, payload_dict)
                finally:
                    self._in_callback = False
                if not guard_result:
                    raise ValueError(f"guard rejected event {event!r} in state {self._state!r}")

            if action is not None:
                old_state = self._state
                self._in_callback = True
                try:
                    action(old_state, new_state, event, payload_dict)
                finally:
                    self._in_callback = False

            self._state = new_state
            return self._state
